dataTransform.transform:
edges.node~>|$|{
"headerText":(
$event := $isNilOrEmpty(event.name) ? " " : " : " & event.name;
$title := workcenter.code & " : " & mode.name & $event;

$r := $parseInt($substring(mode.modeType.color,1,2),16);
$g := $parseInt($substring(mode.modeType.color,3,4),16);
$b := $parseInt($substring(mode.modeType.color,5,6),16);

$color := (($r * 0.299) + ($g * 0.587) + ($b * 0.114)) > 186 ? "#000000" : "#ffffff";

"<span style=\"color:" & $color & "; font-size: 50px;font-weight: bold;\">" & $title & "</span>" 

)

}|

(
  $q := $query({"statement":"query($w:ProductionSetupBOMWhereInput){ b:productionSetupBOM(where:$w){edges{node{id standardUsage consumptionModeId productionSetupOutput{workOrderDistribution{balanceQuantity}} workOrderProcess{id code workOrder{number}}workOrderProcess{code quantity} componentProduct{code} componentProductStrategyProcess{id code processId}}}}}","variables":{
    "w": {
      "bomTypeId": {
        "_eq": "Product"
      }, "productionSetupOutput": {
        "productionSetup": {
          "workcenterId": {
            "_in": [$metadata.urlParameters.id]
          }
        }
      }
    }
  }}).b.edges.node;

  $g := $groupBy([$q], function ($v) { $v.componentProductStrategyProcess.id });

  [$each($g, function($v, $k) {(
    {
      "workOrderProcess": $v.($omit($,['componentProduct', 'componentProductStrategyProcess'])),
      "componentProduct": $v[0].componentProduct,
      "componentProductStrategyProcess": $v[0].componentProductStrategyProcess,
      "standardUsage": $sum($v.standardUsage),
      "consumptionModeId": $v[0].consumptionModeId,
      "req": $sum($v.(productionSetupOutput.workOrderDistribution.balanceQuantity * standardUsage))
    }
  )})]
)

